//! `librosa.effects` / `decompose` / `phase_vocoder` / `griffinlim` / `lpc` /
//! `clicks` references (fixture `effects.json`, generated by `cases/effects.py`).
//!
//! Tolerances are peak-relative (`|a - e| <= rtol * max|e|`, see
//! `common::assert_close`). The algorithms follow librosa/SciPy operation by
//! operation; remaining differences are
//! - the FFT (pocketfft vs realfft: ~1e-16 relative per transform), which enters
//!   every STFT-based result and is amplified by the phase vocoder's
//!   `angle()` differences and the Griffin-Lim iterations;
//! - summation order (numpy pairwise sums vs sequential sums, numba loops);
//! - libm `cos`/`sin`/`atan2`/`pow` ulps.
//!
//! `pitch_shift` additionally differs in the resampler (soxr_hq in librosa,
//! the crate's windowed-sinc `High` here), which is checked with an SNR bound.
//! Measured errors are printed with `--nocapture`.

use audio_samples::operations::effects::{
    AudioEffects, ClickPositions, ClicksConfig, GriffinLimConfig, GriffinLimInit,
    HarmonicPercussiveConfig, HpssMaskConfig, NnAggregate, PitchShiftConfig, SilenceConfig, clicks,
    deemphasis_with_state, griffinlim, hpss_magnitude, hpss_masks, hpss_spectrogram, lpc,
    nn_filter, nn_filter_recurrence, phase_vocoder, phase_vocoder_at, preemphasis_with_state,
    softmask,
};
use audio_samples::operations::sequence::{RecurrenceConfig, RecurrenceMode, recurrence_matrix};
use audio_samples::operations::spectrum::{AudioSpectrum, DbReference, StftConfig, istft, stft};
use audio_samples::{AudioSamples, nzu};
use ndarray::{Array2, Array3, Axis, s};
use num_complex::Complex;
use serde_json::Value;

use crate::common::{arr2, assert_close, carr2, errors, f64s, load, mono, signal, sr, stereo};

fn fixture() -> &'static Value {
    static F: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    F.get_or_init(|| load("effects"))
}

fn step(key: &str) -> usize {
    fixture()[key].as_u64().unwrap() as usize
}

fn usize_of(v: &Value) -> usize {
    v.as_u64().expect("integer") as usize
}

#[track_caller]
fn check<'a>(
    what: &str,
    actual: impl IntoIterator<Item = &'a f64> + Clone,
    expected: impl IntoIterator<Item = &'a f64> + Clone,
    rtol: f64,
) {
    let (abs, rel) = errors(actual.clone(), expected.clone());
    eprintln!("{what:<44} max abs {abs:.3e}  peak-rel {rel:.3e}  (rtol {rtol:e})");
    assert_close(what, actual, expected, rtol, 0.0);
}

/// Complex comparison: real and imaginary parts concatenated.
#[track_caller]
fn check_complex(
    what: &str,
    actual: &Array2<Complex<f64>>,
    expected: &Array2<Complex<f64>>,
    rtol: f64,
) {
    assert_eq!(actual.shape(), expected.shape(), "{what}: shape");
    let flat = |a: &Array2<Complex<f64>>| -> Vec<f64> {
        a.iter()
            .map(|z| z.re)
            .chain(a.iter().map(|z| z.im))
            .collect()
    };
    check(what, &flat(actual), &flat(expected), rtol);
}

/// Mono audio samples as a Vec.
fn samples(a: &AudioSamples<'_, f64>) -> Vec<f64> {
    a.as_mono().expect("mono").to_vec()
}

fn strided(x: &[f64], k: usize) -> Vec<f64> {
    x.iter().step_by(k).copied().collect()
}

/// Strided subset `[c, ::bs, ::fs]` of a 3-D array, checked against the stored shape.
fn subset<T: Clone>(a: &Array3<T>, case: &Value) -> Array2<T> {
    let shape: Vec<usize> = case["shape"]
        .as_array()
        .unwrap()
        .iter()
        .map(usize_of)
        .collect();
    assert_eq!(&a.shape()[1..], &shape[..], "full shape");
    let (bs, fs) = (usize_of(&case["bin_step"]), usize_of(&case["frame_step"]));
    a.slice(s![0, ..;bs, ..;fs]).to_owned()
}

fn mix_stft() -> Array3<Complex<f64>> {
    mono("mix").stft_matrix(&StftConfig::librosa()).unwrap()
}

#[test]
fn phase_vocoder_matches() {
    // Same algorithm step by step; the inputs are our STFT (~1e-16 relative from
    // librosa's). The output phase is a running sum of `atan2` differences, so
    // the STFT round-off of low-magnitude bins (whose angle is ill-conditioned)
    // accumulates over the frames: measured 4e-12 to 1.2e-11 peak-relative.
    // Bound 1e-9.
    let f = &fixture()["phase_vocoder"];
    let d = mix_stft();
    for rate in ["0.8", "1.25"] {
        let y = phase_vocoder(d.view(), rate.parse().unwrap()).unwrap();
        check_complex(
            &format!("phase_vocoder rate {rate}"),
            &subset(&y, &f[rate]),
            &carr2(&f[rate]["subset"]),
            1e-9,
        );
    }
    let t_out = f64s(&f["t_out"]["t_out"]);
    let y = phase_vocoder_at(d.view(), &t_out).unwrap();
    check_complex(
        "phase_vocoder t_out",
        &subset(&y, &f["t_out"]),
        &carr2(&f["t_out"]["subset"]),
        1e-9,
    );
}

#[test]
fn time_stretch_matches() {
    // STFT -> phase vocoder -> ISTFT, all librosa-exact; round-off accumulated in
    // the vocoder phase (see phase_vocoder_matches): measured ~6e-11. Bound 1e-9.
    let f = &fixture()["time_stretch"];
    let k = step("sig_step");
    let x = mono("mix");
    for rate in ["1.5", "0.75"] {
        let y = x
            .time_stretch(rate.parse().unwrap(), &StftConfig::librosa())
            .unwrap();
        let y = samples(&y);
        assert_eq!(y.len(), usize_of(&f[rate]["len"]), "length rate {rate}");
        check(
            &format!("time_stretch rate {rate}"),
            &strided(&y, k),
            &f64s(&f[rate]["y"]),
            1e-9,
        );
    }
    let fs = &fixture()["time_stretch_stereo"];
    let y = stereo().time_stretch(1.5, &StftConfig::librosa()).unwrap();
    let y = y.as_multi_channel().unwrap().as_view().to_owned();
    assert_eq!(y.ncols(), usize_of(&fs["len"]));
    let e = arr2(&fs["y"]);
    let a = y.slice(s![.., ..;k]).to_owned();
    check("time_stretch stereo", a.iter(), e.iter(), 1e-9);
}

#[test]
fn pitch_shift_matches() {
    let f = &fixture()["pitch_shift"];
    let k = step("sig_step");
    let x = mono("mix");
    let n = x.samples_per_channel().get();
    for n_steps in ["2", "-3"] {
        let case = &f[n_steps];
        let rate = case["rate"].as_f64().unwrap();
        // The resampler-free stage (time stretch by `rate`) is librosa-exact up to
        // the vocoder round-off (bound as in time_stretch_matches).
        let st = samples(&x.time_stretch(rate, &StftConfig::librosa()).unwrap());
        assert_eq!(st.len(), usize_of(&case["stretched_len"]));
        check(
            &format!("pitch_shift {n_steps}: stretched"),
            &strided(&st, k),
            &f64s(&case["stretched"]),
            1e-9,
        );

        // Final output: librosa resamples with soxr_hq, we with the windowed-sinc
        // `High` quality. Both are near-ideal band-limited interpolators that differ
        // in transition band and stopband; on this signal (energy up to 4 kHz, far
        // below the 10 kHz band edge) they agree to 67-69 dB SNR (measured: +2 st 67.6 dB,
        // -3 st 68.5 dB). Bound: 55 dB, leaving margin for resampler tuning.
        let y = samples(
            &x.pitch_shift(n_steps.parse().unwrap(), &PitchShiftConfig::librosa())
                .unwrap(),
        );
        assert_eq!(y.len(), n);
        assert_eq!(usize_of(&case["len"]), n);
        let a = strided(&y, k);
        let e = f64s(&case["y"]);
        let sig: f64 = e.iter().map(|v| v * v).sum();
        let err: f64 = a.iter().zip(&e).map(|(p, q)| (p - q) * (p - q)).sum();
        let snr = 10.0 * (sig / err).log10();
        let (abs, _) = errors(&a, &e);
        eprintln!(
            "pitch_shift {n_steps:<3} vs librosa (soxr_hq)            SNR {snr:.1} dB  max abs {abs:.3e}"
        );
        assert!(snr > 55.0, "pitch_shift {n_steps}: SNR {snr:.1} dB");
    }
}

#[test]
fn emphasis_matches() {
    // First-order recursions identical to scipy.signal.lfilter: round-off only.
    let f = &fixture()["emphasis"];
    let k = step("sparse_step");
    let x = signal("mix");
    let cases: [(&str, f64, Option<f64>, bool); 4] = [
        ("pre", 0.97, None, true),
        ("pre_coef05_zi025", 0.5, Some(0.25), true),
        ("de", 0.97, None, false),
        ("de_coef08_zim01", 0.8, Some(-0.1), false),
    ];
    for (name, coef, zi, pre) in cases {
        let (y, zf) = if pre {
            preemphasis_with_state(&x, coef, zi).unwrap()
        } else {
            deemphasis_with_state(&x, coef, zi).unwrap()
        };
        check(name, &strided(&y, k), &f64s(&f[name]), 1e-12);
        let ezf = f[format!("{name}_zf")].as_f64().unwrap();
        assert!(
            (zf - ezf).abs() <= 1e-12 * ezf.abs().max(1.0),
            "{name} zf {zf} vs {ezf}"
        );
    }
    let st = stereo();
    let pre = st.preemphasis(0.97).unwrap();
    let de = st.deemphasis(0.97).unwrap();
    for (name, a) in [("pre_stereo_head", pre), ("de_stereo_head", de)] {
        let a = a
            .as_multi_channel()
            .unwrap()
            .as_view()
            .slice(s![.., ..50])
            .to_owned();
        let e = arr2(&f[name]);
        check(name, a.iter(), e.iter(), 1e-12);
    }
    // The trait method equals the free function.
    let m = samples(&mono("mix").preemphasis(0.97).unwrap());
    check(
        "preemphasis trait",
        &strided(&m, k),
        &f64s(&f["pre"]),
        1e-12,
    );
}

fn pairs(v: &Value) -> Vec<(usize, usize)> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|p| (usize_of(&p[0]), usize_of(&p[1])))
        .collect()
}

#[test]
fn trim_split_match() {
    // Frame decisions are exact unless a frame lies within float32 rounding of the
    // threshold (librosa computes the RMS in float32); none does here.
    let f = &fixture()["trim_split"];
    let burst = mono("burst");
    let cases: [(&str, SilenceConfig); 4] = [
        ("default", SilenceConfig::librosa()),
        ("top_db30", SilenceConfig::new(30.0)),
        (
            "frame1024_hop256",
            SilenceConfig::librosa()
                .with_frame_length(nzu!(1024))
                .with_hop_length(nzu!(256)),
        ),
        (
            "ref_abs",
            SilenceConfig::librosa()
                .with_reference(DbReference::Value(0.01))
                .with_top_db(20.0),
        ),
    ];
    for (name, cfg) in cases {
        let (trimmed, bounds) = burst.trim_db(&cfg).unwrap();
        let e = pairs(&serde_json::json!([f[name]["trim"]]))[0];
        assert_eq!(bounds, e, "trim {name}");
        assert_eq!(trimmed.samples_per_channel().get(), e.1 - e.0);
        assert_eq!(
            burst.split_db(&cfg).unwrap(),
            pairs(&f[name]["split"]),
            "split {name}"
        );
        eprintln!("trim/split {name:<20} {bounds:?} (exact)");
    }
    let cfg20 = SilenceConfig::new(20.0);
    assert_eq!(
        mono("mix").split_db(&cfg20).unwrap(),
        pairs(&f["mix_split"])
    );
    assert_eq!(
        stereo().split_db(&cfg20).unwrap(),
        pairs(&f["stereo_split_top_db20"])
    );
}

#[test]
fn remix_matches() {
    // Pure index manipulation: exact.
    let f = &fixture()["remix"];
    let k = step("sig_step");
    let intervals = pairs(&f["intervals"]);
    for align in [true, false] {
        let case = &f[format!("align_{}", if align { "True" } else { "False" })];
        let y = samples(&mono("mix").remix(&intervals, align).unwrap());
        assert_eq!(
            y.len(),
            usize_of(&case["len"]),
            "remix align={align} length"
        );
        check(
            &format!("remix align={align}"),
            &strided(&y, k),
            &f64s(&case["y"]),
            0.0,
        );
    }
}

fn hpss_cfg(name: &str) -> HpssMaskConfig {
    match name {
        "default" => HpssMaskConfig::librosa(),
        "margin2" => HpssMaskConfig::librosa().with_margin(2.0),
        "kernel_17_9_power1" => HpssMaskConfig::librosa()
            .with_kernel_sizes(nzu!(17), nzu!(9))
            .with_power(1.0),
        "hard" => HpssMaskConfig::librosa().with_power(f64::INFINITY),
        "kernel_even" => HpssMaskConfig::librosa()
            .with_kernel_sizes(nzu!(10), nzu!(12))
            .with_margins(1.0, 3.0),
        other => panic!("unknown hpss case {other}"),
    }
}

#[test]
fn hpss_spectrogram_matches() {
    // Median filtering is exact selection (identical values, SciPy `reflect`
    // boundary and even-kernel rank); the masks are the same arithmetic. Inputs
    // differ by the STFT round-off (~1e-16 relative). Hard masks can flip only
    // where H == P to round-off; none does on this signal.
    let f = &fixture()["hpss_spectrogram"];
    let d = mono("notes").stft_matrix(&StftConfig::librosa()).unwrap();
    for name in [
        "default",
        "margin2",
        "kernel_17_9_power1",
        "hard",
        "kernel_even",
    ] {
        let cfg = hpss_cfg(name);
        let (h, p) = hpss_spectrogram(d.view(), &cfg).unwrap();
        let case = &f[name];
        check_complex(
            &format!("hpss {name}: harmonic"),
            &subset(&h, &case["harm"]),
            &carr2(&case["harm"]["subset"]),
            1e-10,
        );
        check_complex(
            &format!("hpss {name}: percussive"),
            &subset(&p, &case["perc"]),
            &carr2(&case["perc"]["subset"]),
            1e-10,
        );
        let mag = d.mapv(Complex::norm);
        let (mh, mp) = hpss_masks(mag.view(), &cfg).unwrap();
        let (a, e) = (
            subset(&mh, &case["mask_harm"]),
            arr2(&case["mask_harm"]["subset"]),
        );
        check(
            &format!("hpss {name}: mask harmonic"),
            a.iter(),
            e.iter(),
            1e-9,
        );
        let (a, e) = (
            subset(&mp, &case["mask_perc"]),
            arr2(&case["mask_perc"]["subset"]),
        );
        check(
            &format!("hpss {name}: mask percussive"),
            a.iter(),
            e.iter(),
            1e-9,
        );
    }
    let mag = d.mapv(Complex::norm);
    let (h, p) = hpss_magnitude(mag.view(), &HpssMaskConfig::librosa()).unwrap();
    let case = &f["magnitude_default"];
    let (a, e) = (subset(&h, &case["harm"]), arr2(&case["harm"]["subset"]));
    check("hpss magnitude: harmonic", a.iter(), e.iter(), 1e-10);
    let (a, e) = (subset(&p, &case["perc"]), arr2(&case["perc"]["subset"]));
    check("hpss magnitude: percussive", a.iter(), e.iter(), 1e-10);
}

#[test]
fn hpss_audio_matches() {
    // STFT -> HPSS -> ISTFT, all librosa-exact: round-off only.
    let f = &fixture()["hpss_audio"];
    let k = step("sparse_step");
    let x = mono("notes");
    let def = HarmonicPercussiveConfig::librosa();
    let (h, p) = x.harmonic_percussive(&def).unwrap();
    check(
        "effects.hpss harmonic",
        &strided(&samples(&h), k),
        &f64s(&f["harmonic"]),
        1e-10,
    );
    check(
        "effects.hpss percussive",
        &strided(&samples(&p), k),
        &f64s(&f["percussive"]),
        1e-10,
    );
    let m2 =
        HarmonicPercussiveConfig::librosa().with_hpss(HpssMaskConfig::librosa().with_margin(2.0));
    let h2 = samples(&x.harmonic(&m2).unwrap());
    let p2 = samples(&x.percussive(&m2).unwrap());
    check(
        "effects.harmonic margin 2",
        &strided(&h2, k),
        &f64s(&f["harmonic_margin2"]),
        1e-10,
    );
    check(
        "effects.percussive margin 2",
        &strided(&p2, k),
        &f64s(&f["percussive_margin2"]),
        1e-10,
    );
}

#[test]
fn softmask_matches() {
    // Same arithmetic (numpy's exact x**2 fast path is reproduced); pow ulps for 3.5.
    let f = &fixture()["softmask"];
    let (x, r) = (arr2(&f["x"]), arr2(&f["x_ref"]));
    for (name, power, split) in [
        ("power1", 1.0, false),
        ("power2_split", 2.0, true),
        ("power3_5", 3.5, false),
        ("inf", f64::INFINITY, false),
    ] {
        let m = softmask(&x, &r, power, split).unwrap();
        let e = arr2(&f[name]);
        check(&format!("softmask {name}"), m.iter(), e.iter(), 1e-14);
    }
}

#[test]
fn griffinlim_matches() {
    // init=None is deterministic; each iteration is an ISTFT/STFT pair with the
    // FFT round-off (~1e-16) fed back, so differences grow with the iteration
    // count: measured ~1e-14 after 8 iterations. Bound 1e-9.
    let f = &fixture()["griffinlim"];
    let k = step("sig_step");
    let n = usize_of(&f["len"]);
    let x = signal("mix");
    let cfg = StftConfig::librosa().with_n_fft(nzu!(512));
    let xa = Array2::from_shape_vec((1, n), x[..n].to_vec()).unwrap();
    let mag = stft(xa.view(), &cfg).unwrap().mapv(Complex::norm);
    let base = GriffinLimConfig::librosa()
        .with_stft(cfg)
        .with_n_iter(usize_of(&f["n_iter"]))
        .with_init(GriffinLimInit::ZeroPhase)
        .with_length(Some(n));
    for (name, gl) in [
        ("momentum099", base.clone()),
        ("momentum0", base.clone().with_momentum(0.0)),
        ("no_length", base.clone().with_n_iter(4).with_length(None)),
    ] {
        let y = griffinlim(mag.view(), &gl).unwrap();
        let y = y.index_axis(Axis(0), 0).to_vec();
        check(
            &format!("griffinlim {name}"),
            &strided(&y, k),
            &f64s(&f[name]),
            1e-9,
        );
    }
    let rate = std::num::NonZeroU32::new(sr()).unwrap();
    let audio = AudioSamples::<f64>::griffinlim_audio(&mag, &base, rate).unwrap();
    check(
        "griffinlim_audio",
        &strided(&samples(&audio), k),
        &f64s(&f["momentum099"]),
        1e-9,
    );
}

#[test]
fn nn_filter_matches() {
    // The recurrence matrix is computed by our `sequence::recurrence_matrix`
    // (exact neighbour sets); aggregation is the same arithmetic.
    let f = &fixture()["nn_filter"];
    let chroma = arr2(&f["chroma"]);
    let mean = nn_filter_recurrence(
        chroma.view(),
        &RecurrenceConfig::default(),
        NnAggregate::Mean,
    )
    .unwrap();
    check(
        "nn_filter mean",
        mean.iter(),
        arr2(&f["mean"]).iter(),
        1e-12,
    );
    let median = nn_filter_recurrence(
        chroma.view(),
        &RecurrenceConfig::default(),
        NnAggregate::Median,
    )
    .unwrap();
    check(
        "nn_filter median",
        median.iter(),
        arr2(&f["median"]).iter(),
        1e-12,
    );
    let rec = recurrence_matrix(
        chroma.view(),
        &RecurrenceConfig::new()
            .with_mode(RecurrenceMode::Affinity)
            .with_sym(true),
    )
    .unwrap();
    let avg = nn_filter(chroma.view(), rec.view(), NnAggregate::WeightedAverage).unwrap();
    check(
        "nn_filter affinity average",
        avg.iter(),
        arr2(&f["affinity_sym_average"]).iter(),
        1e-10,
    );
}

#[test]
fn lpc_matches() {
    // Burg recursion exactly as librosa's numba kernel (sequential sums in the same
    // order); measured bit-identical. Bound 1e-9 allows for FMA contraction or a
    // different numba reduction order on other machines.
    let f = &fixture()["lpc"];
    for (sig, order) in [("mix", 4usize), ("mix", 16), ("noise", 4), ("noise", 16)] {
        let a = lpc(&signal(sig), std::num::NonZeroUsize::new(order).unwrap()).unwrap();
        check(
            &format!("lpc {sig} order {order}"),
            &a,
            &f64s(&f[format!("{sig}_{order}")]),
            1e-9,
        );
    }
    let a = mono("mix").lpc(nzu!(4)).unwrap();
    check("lpc trait", a.iter(), f64s(&f["mix_4"]).iter(), 1e-9);
}

#[test]
fn clicks_match() {
    // librosa accumulates into float32: agreement to float32 rounding (~6e-8).
    let f = &fixture()["clicks"];
    let k = step("sig_step");
    let rate = std::num::NonZeroU32::new(sr()).unwrap();
    let y = clicks::<f64>(
        ClickPositions::Times(&[0.1, 0.5, 0.52]),
        rate,
        &ClicksConfig::librosa(),
    )
    .unwrap();
    let y = samples(&y);
    assert_eq!(y.len(), usize_of(&f["times_len"]));
    check("clicks times", &strided(&y, k), &f64s(&f["times"]), 1e-6);
    let cfg = ClicksConfig::librosa()
        .with_click_freq(2000.0)
        .with_click_duration(0.05)
        .with_length(Some(11000));
    let frames = ClickPositions::Frames {
        frames: &[3, 20, 40],
        hop_length: nzu!(256),
    };
    let y = samples(&clicks::<f64>(frames, rate, &cfg).unwrap());
    check(
        "clicks frames + length",
        &strided(&y, k),
        &f64s(&f["frames_len"]),
        1e-6,
    );
}

#[test]
fn istft_of_vocoded_length() {
    // Sanity: time_stretch equals the explicit stft -> phase_vocoder -> istft chain.
    let x = mono("mix");
    let d = mix_stft();
    let pv = phase_vocoder(d.view(), 1.5).unwrap();
    let n = (x.samples_per_channel().get() as f64 / 1.5).round_ties_even() as usize;
    let chain = istft(pv.view(), &StftConfig::librosa(), Some(n)).unwrap();
    let ts = samples(&x.time_stretch(1.5, &StftConfig::librosa()).unwrap());
    check(
        "time_stretch == chain",
        &ts,
        chain.index_axis(Axis(0), 0).to_vec().iter(),
        0.0,
    );
}

// ---------------------------------------------------------------------------
// float32: AudioSamples<f32> against librosa run on float32 input
// ---------------------------------------------------------------------------

/// A shared test signal as mono f32 audio (exact: the signals are 16-bit PCM).
fn mono32(name: &str) -> AudioSamples<'static, f32> {
    let x: Vec<f32> = signal(name).iter().map(|&v| v as f32).collect();
    let rate = std::num::NonZeroU32::new(sr()).unwrap();
    AudioSamples::new_mono(ndarray::Array1::from(x), rate).unwrap()
}

/// Mono f32 audio samples widened to f64 (exact).
fn samples32(a: &AudioSamples<'_, f32>) -> Vec<f64> {
    a.as_mono()
        .expect("mono")
        .iter()
        .map(|&v| f64::from(v))
        .collect()
}

fn f32_case() -> &'static Value {
    &fixture()["float32"]
}

/// Peak-relative error of `a` against `e` (for reporting f32-vs-f64 differences).
fn peak_rel(a: &[f64], e: &[f64]) -> f64 {
    errors(a, e).1
}

#[test]
fn f32_time_stretch_matches_librosa_float32() {
    // librosa's float32 STFT multiplies the frames by a float64 window, so its
    // FFT runs in float64 and only the result is rounded to complex64. f32
    // time_stretch does the same (f64 STFT of the samples, rounded once to
    // Complex<f32>), then runs the phase vocoder and the inverse STFT in f32.
    // Measured against librosa float32: 1.9e-7 (rate 1.5) / 1.8e-7 (rate 0.75)
    // peak-relative. Bound 1e-6 (about 8 f32 eps of 1.19e-7: angle, cos/sin,
    // interpolation and the inverse FFT each round in f32).
    //
    // The angles are computed with f64 atan2 and rounded. With atan2f the error
    // was 7.2e-7 under glibc 2.39, over the bound, and 1.2e-7 under 2.43; f64
    // atan2 gives one result under both. Measured 1.2e-7 on 2.39, 2.43 and 2.44.
    //
    // Against our f64 path the rounding of the STFT to Complex<f32> is the
    // difference; the vocoder accumulates the phase of every bin, including
    // bins at the round-off level of the transform, so it grows beyond f32
    // eps: measured 2.1e-6 / 1.9e-6. Bound 1e-5.
    let f = &f32_case()["time_stretch"];
    let k = step("sig_step");
    let x32 = mono32("mix");
    let x64 = mono("mix");
    for rate in ["1.5", "0.75"] {
        let r: f64 = rate.parse().unwrap();
        let y = samples32(&x32.time_stretch(r, &StftConfig::librosa()).unwrap());
        assert_eq!(y.len(), usize_of(&f[rate]["len"]), "length rate {rate}");
        check(
            &format!("f32 time_stretch rate {rate} vs librosa float32"),
            &strided(&y, k),
            &f64s(&f[rate]["y"]),
            1e-6,
        );
        let y64 = samples(&x64.time_stretch(r, &StftConfig::librosa()).unwrap());
        check(
            &format!("f32 time_stretch rate {rate} vs our f64"),
            &y,
            &y64,
            1e-5,
        );
    }
}

#[test]
fn f32_emphasis_matches_librosa_float32() {
    let f = &f32_case()["emphasis"];
    let k = step("sparse_step");
    let x32 = mono32("mix");
    let pre = samples32(&x32.preemphasis(0.97).unwrap());
    let de = samples32(&x32.deemphasis(0.97).unwrap());
    // scipy.signal.lfilter runs the same float32 recursion: measured identical
    // (0 error). Bound: one f32 eps (1.19e-7) of the peak.
    check(
        "f32 preemphasis",
        &strided(&pre, k),
        &f64s(&f["pre"]),
        1.2e-7,
    );
    check("f32 deemphasis", &strided(&de, k), &f64s(&f["de"]), 1.2e-7);
    let x64 = mono("mix");
    eprintln!(
        "f32 preemphasis vs f64 path peak-rel {:.3e}; deemphasis {:.3e}",
        peak_rel(&pre, &samples(&x64.preemphasis(0.97).unwrap())),
        peak_rel(&de, &samples(&x64.deemphasis(0.97).unwrap()))
    );
}

/// `Complex<f32>` array widened to `Complex<f64>`.
fn widen_c(a: &Array3<Complex<f32>>) -> Array3<Complex<f64>> {
    a.mapv(|z| Complex::new(f64::from(z.re), f64::from(z.im)))
}

#[test]
fn f32_hpss_matches_librosa_float32() {
    let f = &f32_case()["hpss_spectrogram"];
    // Our f32 STFT is computed in f32, librosa's in float64 and rounded; the
    // median filters select the same values and the masks repeat the arithmetic
    // in f32. Measured: spectrogram 3.3e-8 (harmonic) / 2.4e-7 (percussive),
    // audio 2.6e-7 / 1.8e-7 peak-relative. Bound 1e-6 (about 8 f32 eps: the
    // 2048-point FFT and inverse FFT round in f32 at every stage).
    let d32 = mono32("notes").stft_matrix(&StftConfig::librosa()).unwrap();
    let (h, p) = hpss_spectrogram(d32.view(), &HpssMaskConfig::librosa()).unwrap();
    let (h, p) = (widen_c(&h), widen_c(&p));
    check_complex(
        "f32 hpss harmonic",
        &subset(&h, &f["harm"]),
        &carr2(&f["harm"]["subset"]),
        1e-6,
    );
    check_complex(
        "f32 hpss percussive",
        &subset(&p, &f["perc"]),
        &carr2(&f["perc"]["subset"]),
        1e-6,
    );

    let f = &f32_case()["hpss_audio"];
    let k = step("sparse_step");
    let (yh, yp) = mono32("notes")
        .harmonic_percussive(&HarmonicPercussiveConfig::librosa())
        .unwrap();
    let (yh, yp) = (samples32(&yh), samples32(&yp));
    check(
        "f32 effects.hpss harmonic",
        &strided(&yh, k),
        &f64s(&f["harmonic"]),
        1e-6,
    );
    check(
        "f32 effects.hpss percussive",
        &strided(&yp, k),
        &f64s(&f["percussive"]),
        1e-6,
    );
    let (h64, p64) = mono("notes")
        .harmonic_percussive(&HarmonicPercussiveConfig::librosa())
        .unwrap();
    eprintln!(
        "f32 effects.hpss vs f64 path peak-rel harmonic {:.3e} percussive {:.3e}",
        peak_rel(&yh, &samples(&h64)),
        peak_rel(&yp, &samples(&p64))
    );
}

#[test]
fn f32_trim_split_match_librosa_float32() {
    // Frame RMS and dB levels in f32 as librosa's float32 run: the decisions are
    // exact unless a frame lies within f32 round-off of the threshold; none does.
    let f = &f32_case()["trim_split"];
    let burst = mono32("burst");
    let cases: [(&str, SilenceConfig); 4] = [
        ("default", SilenceConfig::librosa()),
        ("top_db30", SilenceConfig::new(30.0)),
        (
            "frame1024_hop256",
            SilenceConfig::librosa()
                .with_frame_length(nzu!(1024))
                .with_hop_length(nzu!(256)),
        ),
        (
            "ref_abs",
            SilenceConfig::new(20.0).with_reference(DbReference::Value(0.01)),
        ),
    ];
    for (name, cfg) in cases {
        let (trimmed, bounds) = burst.trim_db(&cfg).unwrap();
        let e = pairs(&serde_json::json!([f[name]["trim"]]))[0];
        assert_eq!(bounds, e, "f32 trim {name}");
        assert_eq!(trimmed.samples_per_channel().get(), e.1 - e.0);
        assert_eq!(
            burst.split_db(&cfg).unwrap(),
            pairs(&f[name]["split"]),
            "f32 split {name}"
        );
        eprintln!("f32 trim/split {name:<20} {bounds:?} (exact)");
    }
    assert_eq!(
        mono32("mix").split_db(&SilenceConfig::new(20.0)).unwrap(),
        pairs(&f["mix_split"])
    );
}

#[test]
fn f32_lpc_matches_librosa() {
    // The recursion runs in f64 for every input type and the coefficients are
    // rounded to f32 once. f32 input holds the same PCM values as the f64
    // signal, so the result is the f64 result rounded: compared with librosa's
    // float64 coefficients the error is half an f32 ulp plus the f64 agreement.
    // Measured: mix order 4 2.9e-8, mix order 16 1.9e-8, noise order 16 3.7e-10
    // peak-relative. Bound 1.2e-7 (one f32 eps).
    let f = &fixture()["lpc"];
    for (sig, order) in [("mix", 4usize), ("mix", 16), ("noise", 16)] {
        let x: Vec<f32> = signal(sig).iter().map(|&v| v as f32).collect();
        let a = lpc(&x, std::num::NonZeroUsize::new(order).unwrap()).unwrap();
        let a: Vec<f64> = a.iter().map(|&v| f64::from(v)).collect();
        check(
            &format!("f32 lpc {sig} order {order} vs librosa float64"),
            &a,
            &f64s(&f[format!("{sig}_{order}")]),
            1.2e-7,
        );
    }
    // Against librosa's float32 recursion only where it is stable (noise). Its
    // float32 round-off is the difference: measured 3.2e-8 at orders 4 and 16.
    // Bound 1e-6.
    let f = &f32_case()["lpc"];
    for order in [4usize, 16] {
        let x: Vec<f32> = signal("noise").iter().map(|&v| v as f32).collect();
        let a = lpc(&x, std::num::NonZeroUsize::new(order).unwrap()).unwrap();
        let a: Vec<f64> = a.iter().map(|&v| f64::from(v)).collect();
        check(
            &format!("f32 lpc noise order {order} vs librosa float32"),
            &a,
            &f64s(&f[format!("noise_{order}")]),
            1e-6,
        );
    }
    // The trait method on f32 audio gives the same rounded coefficients.
    let a = mono32("mix").lpc(nzu!(16)).unwrap();
    let x: Vec<f32> = signal("mix").iter().map(|&v| v as f32).collect();
    let b = lpc(&x, nzu!(16)).unwrap();
    assert_eq!(a.row(0).to_vec(), b);
}

#[test]
fn f32_clicks_match_librosa_float32() {
    // librosa.clicks returns float32 by default; clicks::<f32> is the equivalent.
    let f = &fixture()["clicks"];
    let k = step("sig_step");
    let rate = std::num::NonZeroU32::new(sr()).unwrap();
    let y = clicks::<f32>(
        ClickPositions::Times(&[0.1, 0.5, 0.52]),
        rate,
        &ClicksConfig::librosa(),
    )
    .unwrap();
    // The click is computed in f64 and rounded to f32 once, then summed in f32
    // (librosa does the same in float32): measured 5.3e-8 peak-relative. Bound:
    // two f32 eps (2.4e-7).
    let y = samples32(&y);
    check(
        "f32 clicks times",
        &strided(&y, k),
        &f64s(&f["times"]),
        2.4e-7,
    );
}
